void Solver::restart() {
    // Reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;

    // Reset activity scaling to avoid overflow and give fresh VSIDS scores
    var_inc = 1.0;
    for (int v = 1; v <= vars; ++v) {
        activity[v] = 1.0;
    }

    // Clear VSIDS heap and re‑insert all unassigned variables
    while (!vsids.empty()) vsids.pop();
    for (int v = 1; v <= vars; ++v) {
        if (value[v] == 0) {
            if (!vsids.inHeap(v)) vsids.insert(v);
        }
    }

    // Backtrack to root level
    backtrack(0);

    // Phase selection: mostly use the best local phase, occasionally random
    int r = rand() % 100;
    if (r < 70) {
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else {
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    }
}
